-- Hosbah queries (MH-575 H7).

-- name: UpsertApmIssueSeen :one
-- One row per (app, fingerprint). A new occurrence bumps count and last_seen, and reopens an issue
-- that had been marked resolved (a fixed bug that regressed is news again); an ignored issue stays
-- ignored (that is a deliberate, sticky decision, not something a new occurrence should undo).
INSERT INTO apm_issues (team_id, app_id, fingerprint, type, message, first_seen, last_seen, count, status)
VALUES (sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('fingerprint'), sqlc.arg('type'), sqlc.arg('message'),
        sqlc.arg('seen_at'), sqlc.arg('seen_at'), 1, 'open')
ON CONFLICT (app_id, fingerprint) DO UPDATE SET
  count = apm_issues.count + 1,
  last_seen = sqlc.arg('seen_at'),
  message = sqlc.arg('message'),
  status = CASE WHEN apm_issues.status = 'resolved' THEN 'open' ELSE apm_issues.status END,
  updated_at = now()
RETURNING *;

-- name: ApmIssuesOfApp :many
SELECT * FROM apm_issues
WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id') AND last_seen >= sqlc.arg('since')
ORDER BY last_seen DESC
LIMIT 100;

-- name: ApmIssueOfApp :one
SELECT * FROM apm_issues WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id') AND id = sqlc.arg('id');

-- name: SetApmIssueStatus :one
UPDATE apm_issues SET status = sqlc.arg('status'), updated_at = now()
WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id') AND id = sqlc.arg('id')
RETURNING *;

-- name: DeleteOldApmIssuesSystem :execrows
-- System scope, the retention sweep: drop issues whose last occurrence has aged out of the
-- exception-event retention window (30 days) and that have no events left referencing them.
DELETE FROM apm_issues WHERE last_seen < sqlc.arg('before');
